import { test } from 'node:test';
import assert from 'node:assert/strict';
import { exportCsv } from '../export.mjs';

test('exports a header and one record [EXP-001] [Test-type: Unit]', () => {
  assert.equal(exportCsv([{name: 'Ada'}], ['name']), 'name\r\nAda\r\n');
});

test('selects and orders explicit columns for every record [EXP-002] [Test-type: Unit]', () => {
  const records = [{name: 'Ada', city: 'London', hidden: 'ignore'}, {name: 'Grace', city: 'New York', hidden: 'ignore'}];
  assert.equal(exportCsv(records, ['city', 'name']), 'city,name\r\nLondon,Ada\r\nNew York,Grace\r\n');
});

test('quotes comma fields in values and headers and leaves plain fields unquoted [EXP-003] [Test-type: Unit]', () => {
  assert.equal(exportCsv([{'home,city': 'London, UK', name: 'Ada'}], ['home,city', 'name']), '"home,city",name\r\n"London, UK",Ada\r\n');
  assert.equal(exportCsv([{value: ''}], ['value']), 'value\r\n\r\n');
});

test('doubles embedded quotes in values and headers [EXP-004] [Test-type: Unit]', () => {
  assert.equal(exportCsv([{value: 'Say "hello"'}, {value: 'Say "hello", Ada'}, {value: '""'}], ['value']), 'value\r\n"Say ""hello"""\r\n"Say ""hello"", Ada"\r\n""""""\r\n');
  assert.equal(exportCsv([{'a"b': 'x'}], ['a"b']), '"a""b"\r\nx\r\n');
});

test('preserves LF, CR, and CRLF inside quoted fields [EXP-005] [Test-type: Unit]', () => {
  for (const newline of ['\n', '\r', '\r\n']) {
    assert.equal(exportCsv([{value: `first${newline}second`}], ['value']), `value\r\n"first${newline}second"\r\n`);
    assert.equal(exportCsv([{value: `"first",${newline}second`}], ['value']), `value\r\n"""first"",${newline}second"\r\n`);
    const header = `a${newline}b`;
    assert.equal(exportCsv([{[header]: 'x'}], [header]), `"${header}"\r\nx\r\n`);
  }
});

test('exports only the escaped header for an empty record list [EXP-006] [Test-type: Unit]', () => {
  assert.equal(exportCsv([], ['name', 'city']), 'name,city\r\n');
  assert.equal(exportCsv([], ['home,city', 'a"b', 'line\nbreak']), '"home,city","a""b","line\nbreak"\r\n');
});

// Optional UTF-8 byte order mark. The same escaping-heavy input is used on the
// default, disabled, and enabled paths so preservation is checked on each one.
const BOM_BYTES = [0xef, 0xbb, 0xbf];
const specialColumns = ['home,city', 'a"b', 'note'];
const specialRecords = [
  {'home,city': 'London, UK', 'a"b': 'Say "hello"', note: 'first\r\nsecond'},
  {'home,city': 'Paris', 'a"b': 'plain', note: 'line\nbreak'},
];
const specialCsv = '"home,city","a""b",note\r\n"London, UK","Say ""hello""","first\r\nsecond"\r\nParis,plain,"line\nbreak"\r\n';
const startsWithBomBytes = text => BOM_BYTES.every((byte, index) => Buffer.from(text, 'utf8')[index] === byte);

test('omits the byte order mark when options are omitted [EXP-007] [Test-type: Unit] [Case: omitted-options] [Coverage: positive]', () => {
  const output = exportCsv(specialRecords, specialColumns);
  assert.equal(output, specialCsv);
  assert.notEqual(output.charCodeAt(0), 0xfeff);
  assert.equal(startsWithBomBytes(output), false);
});

test('omits the byte order mark for empty options or bom false [EXP-007] [Test-type: Unit] [Case: explicit-false-or-empty] [Coverage: negative]', () => {
  for (const options of [{}, {bom: false}]) {
    const output = exportCsv(specialRecords, specialColumns, options);
    assert.equal(output, specialCsv);
    assert.equal(output.includes('\uFEFF'), false);
    assert.equal(startsWithBomBytes(output), false);
  }
});

test('adds one byte order mark before an escaped header and records [EXP-008] [Test-type: Unit] [Case: records-with-escaping] [Coverage: positive]', () => {
  const output = exportCsv(specialRecords, specialColumns, {bom: true});
  assert.equal(output, `\uFEFF${specialCsv}`);
  assert.deepEqual(Buffer.from(output, 'utf8'), Buffer.concat([Buffer.from(BOM_BYTES), Buffer.from(specialCsv, 'utf8')]));
});

test('adds the byte order mark only at the start of multi-row output [EXP-008] [Test-type: Unit] [Case: single-marker] [Coverage: negative]', () => {
  const records = [{name: 'Ada'}, {name: 'Grace'}, {name: 'Linus'}];
  const output = exportCsv(records, ['name'], {bom: true});
  assert.equal(output.indexOf('\uFEFF'), 0);
  assert.equal(output.lastIndexOf('\uFEFF'), 0);
  assert.equal(output.slice(1), 'name\r\nAda\r\nGrace\r\nLinus\r\n');
});

test('adds the byte order mark before an escaped header with no records [EXP-009] [Test-type: Unit] [Case: escaped-header] [Coverage: boundary]', () => {
  const output = exportCsv([], ['home,city', 'a"b', 'line\nbreak'], {bom: true});
  assert.equal(output, '\uFEFF"home,city","a""b","line\nbreak"\r\n');
  assert.deepEqual([...Buffer.from(output, 'utf8').subarray(0, 4)], [...BOM_BYTES, 0x22]);
});

test('adds the byte order mark before a plain header with no records [EXP-009] [Test-type: Unit] [Case: plain-header] [Coverage: positive]', () => {
  assert.equal(exportCsv([], ['name', 'city'], {bom: true}), '\uFEFFname,city\r\n');
});

test('omits the byte order mark for no records when bom is false [EXP-009] [Test-type: Unit] [Case: empty-without-option] [Coverage: negative]', () => {
  const output = exportCsv([], ['name', 'city'], {bom: false});
  assert.equal(output, 'name,city\r\n');
  assert.equal(startsWithBomBytes(output), false);
});

